(() => {
  const attach = (form) => {
    const labelInput = form.querySelector('#label');
    const machineInput = form.querySelector('#machine_name');
    if (!labelInput || !machineInput) {
      return;
    }

    const csrfInput = form.querySelector('input[name="csrf_token"]');
    const buildFormData = () => {
      const formData = new FormData();
      formData.set('type', form.dataset.machineNameContext || 'form');
      formData.set('label', labelInput.value || '');
      formData.set('machine_name', machineInput.value || '');

      if (form.dataset.machineNameContext === 'field') {
        const formIDInput = form.querySelector('input[name="form_id"]');
        if (formIDInput) {
          formData.set('form_id', formIDInput.value);
        }
      }

      if (csrfInput) {
        formData.set('csrf_token', csrfInput.value);
      }

      return formData;
    };

    const shouldSuggest = () => machineInput.value.trim().length === 0;

    const updateFromServer = async () => {
      if (!shouldSuggest()) {
        return;
      }

      if (!labelInput.value.trim()) {
        machineInput.value = '';
        return;
      }

      try {
        const response = await fetch('/eav/machine-name/suggest', {
          method: 'POST',
          credentials: 'same-origin',
          body: buildFormData(),
        });

        if (!response.ok) {
          return;
        }

        const payload = await response.json();
        if (shouldSuggest() && payload && typeof payload.machine_name === 'string') {
          machineInput.value = payload.machine_name;
        }
      } catch (err) {
        console.warn('machine name suggest error', err);
      }
    };

    labelInput.addEventListener('blur', updateFromServer);
  };

  const forms = document.querySelectorAll('[data-machine-name-context]');
  forms.forEach(attach);
})();
